steps.run:
set -euo pipefail
mkdir -p "$RUNNER_TEMP/cruixe-source" "$RUNNER_TEMP/cruixe-deps" "$RUNNER_TEMP/cruixe-evidence"
python3 - <<'PY'
import hashlib,json,os,tarfile
from pathlib import Path,PurePosixPath
review=Path(os.environ['REVIEW_PATH'])
manifest=json.loads((review/'review-manifest.json').read_text())
archive=review/'approved-frontend-ci.tgz'
if hashlib.sha256(archive.read_bytes()).hexdigest()!=manifest['archiveSHA256']: raise SystemExit('Archive SHA mismatch')
if manifest['nodeImage']!=os.environ['NODE_IMAGE']: raise SystemExit('Unexpected runtime image')
expected={f['path']:f for f in manifest['files']}
if len(expected)!=len(manifest['files']): raise SystemExit('Duplicate manifest path')
target=Path(os.environ['RUNNER_TEMP'])/'cruixe-source'
seen=set();total=0
with tarfile.open(archive,'r:gz') as source:
  for member in source:
    p=PurePosixPath(member.name)
    if not member.isfile() or p.is_absolute() or '..' in p.parts or member.name not in expected or member.name in seen: raise SystemExit('Unsafe archive member')
    if any(part.startswith('.env') or part in ('.git','node_modules','.npmrc') for part in p.parts): raise SystemExit('Forbidden snapshot path')
    total+=member.size
    if member.size>32*1024*1024 or total>256*1024*1024: raise SystemExit('Snapshot exceeds size guard')
    data=source.extractfile(member).read()
    if hashlib.sha256(data).hexdigest()!=expected[member.name]['sha256']: raise SystemExit('File SHA mismatch: '+member.name)
    dest=target/member.name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(data);seen.add(member.name)
if seen!=set(expected): raise SystemExit('Missing snapshot files')
for name in ('package.json','package-lock.json'):
  (Path(os.environ['RUNNER_TEMP'])/'cruixe-deps'/name).write_bytes((target/name).read_bytes())
(Path(os.environ['RUNNER_TEMP'])/'cruixe-evidence'/'snapshot-verified.json').write_text(json.dumps({'status':'PASS','archiveSHA256':manifest['archiveSHA256'],'files':len(seen)},indent=2))
PY
